#include <iostream>
#include <vector>
#include <cassert>
using namespace std;

struct MatrixStruct {
    int rowCount, colCount;
    vector<long long> vals;
    MatrixStruct(int r=0,int c=0):rowCount(r),colCount(c),vals(r*c){}
    long long& index(int r,int c){return vals[r*colCount+c];}
    long long index(int r,int c)const{return vals[r*colCount+c];}
    MatrixStruct& add(const MatrixStruct& m){
        assert(rowCount==m.rowCount && colCount==m.colCount);
        for(int i=0;i<rowCount*colCount;++i)vals[i]+=m.vals[i];
        return *this;
    }
    MatrixStruct& subtract(const MatrixStruct& m){
        assert(rowCount==m.rowCount && colCount==m.colCount);
        for(int i=0;i<rowCount*colCount;++i)vals[i]-=m.vals[i];
        return *this;
    }
    MatrixStruct& multiply(const MatrixStruct& m){
        assert(colCount==m.rowCount);
        MatrixStruct result(rowCount,m.colCount);
        for(int i=0;i<rowCount;++i){
            for(int j=0;j<m.colCount;++j){
                for(int k=0;k<colCount;++k){
                    result.index(i,j)+=index(i,k)*m.index(k,j)%mod;
                }
                result.index(i,j)%=mod;
            }
        }
        *this=result;
        return *this;
    }
    static MatrixStruct identity(int n){
        MatrixStruct res(n,n);
        for(int i=0;i<n;++i)res.index(i,i)=1;
        return res;
    }
    static MatrixStruct power(MatrixStruct a,int n){
        assert(a.rowCount==a.colCount);
        MatrixStruct res=identity(a.rowCount);
        while(n){
            if(n&1)res.multiply(a);
            a.multiply(a);
            n>>=1;
        }
        return res;
    }
};

vector<MatrixStruct> matrices(65);
long long compute(int i,int k){
    return MatrixStruct::power(matrices[i+k],k-i)*MatrixStruct::power(matrices[i],i);
}

long long main_process(long long n,long long k){
    long long count=0,tmp=n;
    while(tmp){tmp/=k;++count;}
    vector<MatrixStruct> b(count+5),c(count+5),d(k+1);
    b[0]=matrices[k-1];
    c[0]=MatrixStruct::power(b[0],k-1);
    b[1]=compute(k-1,k);
    c[1]=MatrixStruct::power(b[1],k-1);
    MatrixStruct s=MatrixStruct::identity(2*k+1);
    for(int j=2;j<=count+1;++j){
        b[j]=compute(k-j%k,k);
        s*=c[j-1];
        b[j]*=s;
        c[j]=MatrixStruct::power(b[j],k-1);
    }
    int idx=1,rem=n%k;
    n-=rem;
    int q=0;
    long long tmp2=n;
    if(tmp2){while(tmp2%k==0){++q;tmp2/=k;}}
    q=(k-q%k)%k;
    MatrixStruct ans=MatrixStruct::identity(2*k+1);
    ans=MatrixStruct::power(matrices[q],rem)*MatrixStruct::power(matrices[q+k],max(rem-q,0));
    n/=k;
    if(n==0){return (ans.index(2*k,0)+ans.index(0,0))%mod;}
    --n;
    while(n){
        int t=n%k;
        if(t){ans*=MatrixStruct::power(b[idx],t);}
        n/=k;++idx;
    }
    ans*=b[1];
    return (ans.index(2*k,0)+ans.index(0,0))%mod;
}

int main(){
    long long n,k;
    cin>>n>>k;
    for(int i=0;i<=2*k;++i){
        matrices[i]=MatrixStruct(2*k+1);
        for(int j=0;j<i;++j)matrices[i].index(0,j)=1;
        for(int j=0;j<2*k-1;++j)matrices[i].index(j+1,j)=1;
        matrices[i].index(2*k,0)=1;
        matrices[i].index(2*k,2*k)=1;
    }
    cout<<main_process(n,k)<<endl;
    return 0;
}
